\label{springer_map_lemma}
Let $x,y\in U_1$. Then the following holds.
\begin{enumerate}
    \item If $x\in U_2$ or $y\in U_2$, then $f_{\rm spr}(xy)=f_{\rm spr}(x)+f_{\rm spr}(y)$.
    \item $f_{\rm spr}(xyx^{-1}y^{-1})- [f_{\rm spr}(x),f_{\rm spr}(y)] \in \bigoplus_{i\geq 3}\mathfrak{g}(i)$.
    \item $f_{\rm spr}(F(x)) = F(f_{\rm spr}(x))$.
\end{enumerate}

Let $\rho$ be an irreducible $\mathcal{K}$-representation of $G^F$ with character $\chi_\rho$. Then:
\begin{enumerate}
    \item there exists $u\in C_{\rho^\ast}^F$ such that $\langle\gamma_u^{G^F},\chi_\rho\rangle \ne 0$;
    \item if $C$ is an $F$-stable unipotent conjugacy class of $G$ such that ${\rm dim}(C)> {\rm dim}(C_{\rho^\ast})$, then $\langle\gamma_u^{G^F},\chi_\rho\rangle=0$ for all $u\in C^F$.
\end{enumerate}

Let $G$ be a connected reductive group over $k$ with a Frobenius morphism $F$ on $G$, and assume that $p$ is good for $G$. Then the module 
\begin{equation}\label{progenerator}
\mathscr{P} = \bigoplus_{(L,C)\in\mathscr{L}}R_L^G
(\overline{\Gamma}_C^{G^F})
\end{equation}
is a progenerator of the category of $\ell$-modular representations of $G^F$.

\label{sigma_stable_mult_1_gggr}
Let $\Pi$ be a unipotent cuspidal $\ell$-adic representation of $G^{F^\ell}$ such that $\Pi\simeq \Pi^\sigma$. Then there exists a $\sigma$-stable orbit $[u]$ in $C^{F^\ell}/G^{F^\ell}$ such that 
\begin{equation}\label{mult_1_cusp_unip}
{\rm dim}_{\mathcal{K}}\,{\rm Hom}_{G^{F^\ell}}(\Gamma_u^{G^{F^\ell}}\otimes_\Lambda\mathcal{K},\Pi) = 1.
\end{equation}

By Lemma \ref{sigma_stable_mult_1_gggr}, $\Pi$ is realized as a subrepresentation of $\Gamma_u^{G^{F^\ell}}
\otimes_\Lambda\mathcal{K}$ for a $\sigma$-stable orbit $[u]\in C^{F^\ell}/G^{F^\ell}$. Denote by $\mathcal{W}(\Pi,\widetilde{\eta}_u)$ the realization of $\Pi$ in $\Gamma_u^{G^{F^\ell}}
\otimes_\Lambda\mathcal{K}$. Let $T_\sigma:\mathcal{W}(\Pi,\widetilde{\eta}_u)\rightarrow
\Gamma_u^{G^{F^\ell}}
\otimes_\Lambda\mathcal{K}$ be the linear map defined by $T_\sigma(f)(g) = f(\sigma^{-1}(g))$, for $g\in G^{F^\ell}$. Since the character $\widetilde{\eta}_u$ is $\sigma$-invariant, the image of $T_\sigma$ is equal to $\mathcal{W}(\Pi^\sigma,\widetilde{\eta}_u)$. Since $\Pi\simeq \Pi^\sigma$, it follows from the multiplicity one property of $\Pi$ (Lemma \ref{sigma_stable_mult_1_gggr}) that the image of $T_\sigma$ is $\mathcal{W}(\Pi,\widetilde{\eta}_u)$. Hence, we get the required extension in the lemma. 

For the uniqueness of the $\sigma$-action, let $T_\sigma$ and $T_\sigma'$ be the action of $\sigma$ on $\Pi$ for two different extensions of $\Pi$. Then, using Schur's lemma, we have  $T_\sigma=\lambda T_\sigma'$, for some
$\lambda\in \mathcal{K}$. Since $\lambda^\ell=1$ and $\mathcal{K}$ is the maximal unramified extension of $\mathbb{Q}_\ell$, we conclude that  $\lambda=1$. This completes the proof.

\label{first_tate_trivial}
Let $G$ be a connected reductive group of adjoint type defined over $\mathbb{F}_q$ with corresponding Frobenius map $F$. Assume that $G$ is simple of adjoint type such that $G$ has property $\mathscr{D}$-orbit, and $p$ is good for $G$. Let $\Pi$ be a unipotent cuspidal $\ell$-adic representation of $G^{F^\ell}$. Then, for any $G^{F^\ell}\rtimes\sigma$-stable $\Lambda$-lattice $\mathcal{L}$ in $\Pi$, we have 
$$ \widehat{\rm H}^1(\sigma,\mathcal{L}) = 0. $$

\label{Pro_gen_1}
Let $G$ be as in Theorem \ref{first_tate_trivial}. Assume that $p$ is good for $G$. Let $\mathscr{P}$ be the progenerator as defined by (\ref{progenerator}). Then we have 
$$ {\rm dim}_{\overline
{\mathbb{F}}_\ell}\,{\rm Hom}_{G^F}
(\mathscr{P},\widehat{\rm H}^0(\sigma,
\mathcal{L}))\leq 1. $$
